package org.apache.commons.math.fraction;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.MathIllegalArgumentException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.ZeroException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.ArithmeticUtils;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class BigFraction_pow_TriageGen1Test {

    @Test
    public void testPowPositiveExponent() {
        // Test case: (2/3)^2 = 4/9
        BigFraction fraction = new BigFraction(2, 3);
        BigInteger exponent = BigInteger.valueOf(2);
        BigFraction result = fraction.pow(exponent);

        Assert.assertEquals(new BigInteger("4"), result.getNumerator());
        Assert.assertEquals(new BigInteger("9"), result.getDenominator());
    }

    @Test
    public void testPowZeroExponent() {
        // Test case: (2/3)^0 = 1/1
        BigFraction fraction = new BigFraction(2, 3);
        BigInteger exponent = BigInteger.ZERO;
        BigFraction result = fraction.pow(exponent);

        Assert.assertEquals(BigInteger.ONE, result.getNumerator());
        Assert.assertEquals(BigInteger.ONE, result.getDenominator());
    }

    @Test
    public void testPowNegativeExponent() {
        // Test case: (2/3)^-1 = 3/2
        BigFraction fraction = new BigFraction(2, 3);
        BigInteger exponent = BigInteger.valueOf(-1);
        BigFraction result = fraction.pow(exponent);

        Assert.assertEquals(new BigInteger("3"), result.getNumerator());
        Assert.assertEquals(new BigInteger("2"), result.getDenominator());
    }

    @Test
    public void testPowNegativeLargeExponent() {
        // Test case: (1/2)^-3 = 2^3 / 1^3 = 8/1
        BigFraction fraction = new BigFraction(1, 2);
        BigInteger exponent = BigInteger.valueOf(-3);
        BigFraction result = fraction.pow(exponent);

        Assert.assertEquals(BigInteger.valueOf(8), result.getNumerator());
        Assert.assertEquals(BigInteger.ONE, result.getDenominator());
    }

    @Test
    public void testPowWithLargeBigInteger() {
        // Test case: (1/1)^large = 1/1
        BigFraction fraction = new BigFraction(1, 1);
        // Use a large exponent to ensure BigInteger handling is robust
        BigInteger exponent = new BigInteger("1000000"); 
        BigFraction result = fraction.pow(exponent);

        Assert.assertEquals(BigInteger.ONE, result.getNumerator());
        Assert.assertEquals(BigInteger.ONE, result.getDenominator());
    }

    @Test
    public void testPowWithLargeNumbers() {
        // Test case: (10/1)^10 = 10000000000/1
        BigFraction fraction = new BigFraction(10, 1);
        BigInteger exponent = BigInteger.valueOf(10);
        BigFraction result = fraction.pow(exponent);

        Assert.assertEquals(new BigInteger("10000000000"), result.getNumerator());
        Assert.assertEquals(BigInteger.ONE, result.getDenominator());
    }
}
